/// Returns `true` if and only if for every index `i`,
/// `arr1[i] > arr2[i]`. If both arrays are empty, returns `true`.
pub fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // We assume `arr1.len() == arr2.len()`. If you'd rather handle mismatched lengths,
    // you could return `false` or panic here.
    arr1
        .iter()
        .zip(arr2.iter())
        .all(|(a, b)| a > b)
}

